// Calendar-date helpers. A date is a JS Date at UTC midnight.

export function parseDate(s) {
  const [y, m, d] = s.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d));
}

export function formatDate(date) {
  return date.toISOString().slice(0, 10);
}

export function addMonths(date, months) {
  const next = new Date(date.getTime());
  next.setUTCMonth(next.getUTCMonth() + months);
  return next;
}
import { formatDate, parseDate } from "./dates.js";
import { renewalDates } from "./schedule.js";

const PRICES = { pro: 1200, team: 9900 };

// Upcoming invoice lines for a subscription, e.g.
//   { start: "2024-01-15", plan: "monthly", tier: "pro" }
export function upcomingInvoices(subscription, count = 3) {
  const { start, plan, tier } = subscription;
  const amount = PRICES[tier];
  if (amount === undefined) throw new Error(`unknown tier: ${tier}`);
  return renewalDates(parseDate(start), plan, count).map((date) => ({
    date: formatDate(date),
    description: `${tier} ${plan}`,
    amountCents: plan === "annual" ? amount * 10 : amount,
  }));
}
import { addMonths } from "./dates.js";

const PLAN_MONTHS = { monthly: 1, annual: 12 };

// The next `count` renewal dates for a subscription that started on `start`.
export function renewalDates(start, plan, count) {
  const step = PLAN_MONTHS[plan];
  if (!step) throw new Error(`unknown plan: ${plan}`);
  const dates = [];
  let current = start;
  for (let i = 0; i < count; i++) {
    current = addMonths(current, step);
    dates.push(current);
  }
  return dates;
}
{
  "name": "renewals",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test"
  }
}
import { test } from "node:test";
import assert from "node:assert/strict";
import { parseDate, formatDate } from "../src/dates.js";
import { renewalDates } from "../src/schedule.js";

const dates = (start, plan, n) => renewalDates(parseDate(start), plan, n).map(formatDate);

test("monthly renewals land on the same day each month", () => {
  assert.deepEqual(dates("2024-01-15", "monthly", 3), ["2024-02-15", "2024-03-15", "2024-04-15"]);
});

test("annual renewals land on the same date each year", () => {
  assert.deepEqual(dates("2023-06-10", "annual", 2), ["2024-06-10", "2025-06-10"]);
});

test("unknown plans are rejected", () => {
  assert.throws(() => renewalDates(parseDate("2024-01-01"), "weekly", 1), /unknown plan/);
});

