p='src/dates.js'
s=open(p).read()
i=s.index('export function addMonths')
s=s[:i]+'''// Adds calendar months, clamping to the last day of the target month
// (31 Jan + 1 month = 29 Feb in a leap year).
export function addMonths(date, months) {
  const total = date.getUTCFullYear() * 12 + date.getUTCMonth() + months;
  const year = Math.floor(total / 12);
  const month = total % 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  return new Date(Date.UTC(year, month, Math.min(date.getUTCDate(), lastDay)));
}
'''
open(p,'w').write(s)
p='src/schedule.js'
s=open(p).read()
s=s.replace('''  let current = start;
  for (let i = 0; i < count; i++) {
    current = addMonths(current, step);
    dates.push(current);
  }''','''  // Always offset from `start` so a clamped day (e.g. 29 Feb) doesn't stick.
  for (let i = 1; i <= count; i++) {
    dates.push(addMonths(start, step * i));
  }''')
open(p,'w').write(s)
p='test/schedule.test.js'
s=open(p).read()
s+='''
test("monthly renewals clamp to the last day of short months without drifting", () => {
  assert.deepEqual(dates("2024-01-31", "monthly", 4), ["2024-02-29", "2024-03-31", "2024-04-30", "2024-05-31"]);
});

test("annual renewals from 29 Feb clamp to 28 Feb in non-leap years", () => {
  assert.deepEqual(dates("2024-02-29", "annual", 5), ["2025-02-28", "2026-02-28", "2027-02-28", "2028-02-29", "2029-02-28"]);
});
'''
open(p,'w').write(s)
E
npm test 2>&1 | tail -12

